//verify the flight search request was successful
pm.test("Flight search returns 200 OK", function () {
    pm.response.to.have.status(200);
});

//verify Django returns a flights array
pm.test("Response contains flights array", function () {
    const response = pm.response.json();
    pm.expect(response.flights).to.be.an("array");
});

pm.test("Returns 400 Bad Request", function () {
    pm.response.to.have.status(400);
});

pm.test("Response contains validation error", function () {
    const data = pm.response.json();
    pm.expect(data).to.have.property("error");
});

pm.test("View Reservations returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Reservations are returned as an array", function () {
    const data = pm.response.json();

    pm.expect(data).to.be.an("array");
});

pm.test("API Home returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("API connection message is correct", function () {
    const data = pm.response.json();
    pm.expect(data.message).to.eql(
        "Airplane Reservation API is working!"
    );
});

pm.test("API Health returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("API status is ok", function () {
    const data = pm.response.json();
    pm.expect(data.status).to.eql("ok");
});

pm.test("Customer Count returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Customer count is a nonnegative number", function () {
    const data = pm.response.json();

    pm.expect(data.customer_count).to.be.a("number");
    pm.expect(data.customer_count).to.be.at.least(0);
});

//verify that the account was created
pm.test("Registration returns 201 Created", function () {
    pm.response.to.have.status(201);
});

//verify the response contains customer information
pm.test("Response contains customer ID and username", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("customer_id");
    pm.expect(response).to.have.property("username");
});

//verify the success message
pm.test("Account created successfully", function () {
    const response = pm.response.json();

    pm.expect(response.message).to.eql(
        "Customer account created successfully."
    );
});

pm.test("Missing fields returns 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Required field errors are returned", function () {
    const data = pm.response.json();

    pm.expect(data).to.have.property("f_name");
    pm.expect(data).to.have.property("l_name");
    pm.expect(data).to.have.property("date_of_birth");
    pm.expect(data).to.have.property("username");
    pm.expect(data).to.have.property("password");
});

//verify that an underage customer cannot register
pm.test("Underage registration returns 400", function () {
    pm.response.to.have.status(400);
});

//verify the date of birth validation message
pm.test("Underage registration is rejected", function () {
    const response = pm.response.json();

    pm.expect(response.date_of_birth).to.include(
        "You must be at least 18 years old to create an account."
    );
});

pm.test("Duplicate username returns 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Duplicate username is rejected", function () {
    const data = pm.response.json();

    pm.expect(data.username).to.include(
        "Username is already taken."
    );
});

//verify that mismatched passwords are rejected
pm.test("Password mismatch returns 400", function () {
    pm.response.to.have.status(400);
});

//verify the correct validation message
pm.test("Password mismatch validation works", function () {
    const data = pm.response.json();

    pm.expect(data.confirm_password).to.include(
        "Passwords do not match."
    );
});

pm.test("Login returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Customer login is successful", function () {
    const data = pm.response.json();

    pm.expect(data.message).to.eql(
        "Customer logged in successfully."
    );

    pm.expect(data).to.have.property("customer_id");
    pm.expect(data.username).to.eql(pm.variables.get("testUsername"));
});

pm.test("Invalid login returns 400", function () {
    pm.response.to.have.status(400);
});

pm.test("Login returns validation errors", function () {
    const data = pm.response.json();

    pm.expect(data).to.be.an("object");
    pm.expect(Object.keys(data).length).to.be.above(0);
});

pm.test("Authenticated status returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Customer is authenticated", function () {
    const data = pm.response.json();

    pm.expect(data.authenticated).to.eql(true);
    pm.expect(data).to.have.property("customer_id");
    pm.expect(data).to.have.property("username");
});

pm.test("Unauthenticated status returns 401", function () {
    pm.response.to.have.status(401);
});

pm.test("Customer is not authenticated", function () {
    const data = pm.response.json();

    pm.expect(data.authenticated).to.eql(false);
});

pm.test("Logout returns 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("Customer logged out successfully", function () {
    const data = pm.response.json();

    pm.expect(data.message).to.eql(
        "Customer logged out successfully."
    );
});
